import { useEffect, useMemo, useRef, useCallback } from "react";
import { useSearchParams, useNavigate, useLocation, Link } from "react-router-dom";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import {
  X, ShieldCheck, Shield, ShieldAlert, ShieldX, ArrowUpRight, ArrowLeft, BellOff,
  Loader2, Package, ChevronDown, ExternalLink,
} from "lucide-react";
import { useMarket, useSellerItems, pushRecentlyViewed } from "@/lib/MarketContext";
import { useBlocklist } from "@/lib/useBlocklist";
import ItemDetailContent from "./ItemDetailContent";
import ItemSprite from "./ItemSprite";
import FreshnessPill from "./FreshnessPill";
import ShopDetailPanel from "./ShopDetailPanel";
import ShopLocationPanel from "./ShopLocationPanel";
import { shopLocationKey } from "@/lib/shopLocation";
import useScrollLock from "@/lib/useScrollLock";
import Breadcrumb from "@/components/ui/Breadcrumb";
import { sellerPricingDescription } from "@/lib/sellerPricing";
import { fmt, fmtTime } from "@/lib/parseItem";
import { formatSellerMarkupRange, sellerMarkupRange, sellerMarkupTone } from "@/lib/sellerMarkup";

// ---------- shared atoms ----------

const LABEL_STYLES = {
  "Market-aligned": { icon: ShieldCheck, color: "text-emerald-400", bg: "bg-emerald-500/10", border: "border-emerald-500/30" },
  "Mixed pricing": { icon: Shield, color: "text-sky-400", bg: "bg-sky-500/10", border: "border-sky-500/30" },
  "Frequently above range": { icon: ShieldAlert, color: "text-amber-400", bg: "bg-amber-500/10", border: "border-amber-500/30" },
  "Strongly above range": { icon: ShieldX, color: "text-orange-400", bg: "bg-orange-500/10", border: "border-orange-500/30" },
};

// ---------- SellerPanel ----------

function SellerPanel({ sellerName, onClose, onFilterListings, onOpenItem }) {
  const { sellers, market } = useMarket();
  const { data: sellerItems, loading: itemsLoading, loadingMore } = useSellerItems(sellerName);
  const blocklist = useBlocklist();
  const isBlocked = blocklist.has(sellerName);
  const navigate = useNavigate();
  const seller = useMemo(
    () => sellers?.find((s) => s.name === sellerName) || null,
    [sellers, sellerName]
  );
  const matches = sellerItems?.matches || [];
  const latestSeenMs = matches.reduce((latest, match) => Math.max(latest, match.latestSeenMs || 0), 0);

  if (!seller) {
    return (
      <div className="p-10">
        <div className="font-heading text-xl font-bold mb-2">{sellerName}</div>
        <p className="font-mono text-xs text-zinc-500">Seller not in current dataset.</p>
        <button
          onClick={() => onFilterListings(sellerName)}
          data-testid="seller-view-listings"
          className="mt-6 inline-flex items-center gap-2 bg-emerald-500 hover:bg-emerald-400 text-black font-bold uppercase tracking-[0.18em] text-[11px] px-4 py-2.5 rounded-sm"
        >
          Search listings <ArrowUpRight className="w-3.5 h-3.5" />
        </button>
      </div>
    );
  }

  const label = seller.accuracyLabel || "Mixed pricing";
  const style = LABEL_STYLES[label] || LABEL_STYLES["Mixed pricing"];
  const Icon = style.icon;
  const markup = seller.avgMarkupPercent;
  const isBedrock = seller.identityKey?.startsWith("bedrock");

  return (
    <div className="flex flex-col h-full">
        <div className="sticky top-0 z-10 bg-bg-base/95 backdrop-blur-xl border-b border-white/10 px-5 sm:px-8 py-4 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <button
              onClick={() => navigate(-1)}
              data-testid="seller-back"
              aria-label="Back"
              className="inline-flex items-center gap-1.5 border border-white/15 hover:border-emerald-500 hover:text-emerald-400 text-zinc-300 font-bold uppercase tracking-[0.18em] text-[10px] px-2.5 py-1 rounded-sm transition-colors"
            >
              <ArrowLeft className="w-3 h-3" /> Back
            </button>
            <Breadcrumb
              items={[
                { label: "Home", href: "/" },
                { label: "Sellers", href: "/sellers" },
                { label: seller.name },
              ]}
              color="text-amber-400"
              className="mb-0 text-[10px]"
            />
          </div>
          <div className="flex items-center gap-2">
            <Link
              to={`/sellers/${encodeURIComponent(sellerName)}`}
              data-testid="seller-drawer-full-page"
              className="hidden sm:inline-flex items-center gap-1.5 border border-white/15 hover:border-amber-500 hover:text-amber-400 text-zinc-300 font-bold uppercase tracking-[0.18em] text-[10px] px-2.5 py-1.5 rounded-sm transition-colors"
            >
              Full page <ArrowUpRight className="w-3 h-3" />
            </Link>
            <button onClick={onClose} data-testid="drawer-close" aria-label="Close" className="p-2 text-zinc-400 hover:text-white transition-colors">
              <X className="w-5 h-5" />
            </button>
          </div>
        </div>
      <div className="flex-1 overflow-y-auto overscroll-contain custom-scrollbar touch-pan-y">
        <div className="relative px-5 sm:px-8 pt-7 pb-6 overflow-hidden">
          <div className={`absolute -top-32 -right-20 w-80 h-80 ${style.bg} blur-[100px] rounded-full pointer-events-none`}></div>
          <div className="relative flex items-start gap-5">
            {!isBedrock ? (
              <img
                src={`https://render.crafty.gg/3d/bust/${encodeURIComponent(seller.name)}`}
                alt=""
                width={88}
                height={88}
                loading="lazy"
                decoding="async"
                className="rounded-lg bg-white/[0.05] shrink-0"
                onError={(e) => { e.currentTarget.style.visibility = "hidden"; }}
              />
            ) : (
              <div className="w-22 h-22 rounded-lg bg-white/[0.05] border border-white/10 grid place-items-center text-zinc-500 font-mono uppercase shrink-0">
                {seller.name.slice(0,2)}
              </div>
            )}
            <div className="min-w-0 flex-1">
              <div className="font-mono text-[10px] uppercase tracking-[0.22em] text-amber-400">Seller profile</div>
              <h2 className="mt-1 font-heading text-3xl sm:text-4xl tracking-tighter font-black leading-tight break-words">
                {seller.name}
              </h2>
              <div className="mt-1 font-mono text-[11px] text-zinc-500">
                {isBedrock ? "Bedrock" : seller.uuid ? `Java · ${seller.uuid.slice(0, 8)}` : "—"}
              </div>
              <div className={`mt-3 inline-flex items-center gap-1.5 ${style.bg} ${style.border} border rounded-full px-2.5 py-1`}>
                <Icon className={`w-3 h-3 ${style.color}`} />
                <span className={`font-mono text-[10px] uppercase tracking-wider ${style.color}`}>{label}</span>
              </div>
            </div>
          </div>
        </div>

        <div className="grid grid-cols-3 gap-px bg-white/10 border-y border-white/10">
          <KPI l="Total listings" v={seller.totalListings} />
          <KPI l="Markup" v={`${markup > 0 ? "+" : ""}${markup.toFixed(1)}%`} c={markup > 15 ? "text-red-400" : markup < -10 ? "text-emerald-400" : "text-white"} />
          <KPI l="Above range" v={`${seller.overpricedRatio.toFixed(1)}%`} />
        </div>

        <div className="p-5 sm:p-8 space-y-7">
          <section className="surface-card rounded-xl p-4 sm:p-5">
            <div className="font-mono text-[10px] uppercase tracking-[0.22em] text-[var(--text-muted)] mb-2">Pricing alignment</div>
            <p className="text-[var(--text-secondary)] text-sm leading-relaxed">{sellerPricingDescription(label)} This compares observed asking prices with compatible item medians; it is not a trust or moderation judgment.</p>
          </section>

          <section aria-labelledby="seller-current-listings">
            <div className="mb-3 flex flex-wrap items-end justify-between gap-3">
              <div>
                <div className="font-mono text-[10px] uppercase tracking-[0.22em] text-amber-400">Current observations</div>
                <h3 id="seller-current-listings" className="mt-1 font-heading text-xl sm:text-2xl font-black tracking-tight text-[var(--text-primary)]">What they’re listing</h3>
              </div>
              {latestSeenMs > 0 && <FreshnessPill ms={latestSeenMs} prefix="Latest" size="xs" />}
            </div>

            <div data-testid="seller-drawer-listings" className="overflow-hidden rounded-xl border border-white/10 bg-white/[0.015]">
              {itemsLoading && (
                <div className="flex items-center justify-center gap-2 py-10 text-sm text-[var(--text-muted)]" role="status">
                  <Loader2 className="h-4 w-4 animate-spin" /> Loading seller listings…
                </div>
              )}
              {!itemsLoading && sellerItems?.error && (
                <div className="px-5 py-8 text-center">
                  <p className="text-sm text-red-400">Couldn’t load this seller’s current listings.</p>
                  <p className="mt-1 text-xs text-[var(--text-muted)]">{sellerItems.error}</p>
                </div>
              )}
              {!itemsLoading && !sellerItems?.error && matches.length === 0 && (
                <div className="px-5 py-9 text-center">
                  <Package className="mx-auto h-6 w-6 text-[var(--text-muted)]" />
                  <p className="mt-2 text-sm text-[var(--text-secondary)]">No compatible active listings were found.</p>
                </div>
              )}
              {!itemsLoading && matches.map((match, index) => {
                const row = market?.rowsByKey?.get(match.itemKey);
                const range = sellerMarkupRange(match, row);
                const tone = sellerMarkupTone(range);
                const priceLabel = match.minUnitPrice > 0
                  ? match.minUnitPrice === match.maxUnitPrice
                    ? fmt(match.minUnitPrice)
                    : `${fmt(match.minUnitPrice)}–${fmt(match.maxUnitPrice)}`
                  : "—";
                return (
                  <button
                    key={match.itemKey}
                    type="button"
                    data-testid={`seller-drawer-listing-${index}`}
                    onClick={() => onOpenItem(match.itemKey)}
                    className="group grid w-full grid-cols-[1fr_auto] gap-x-4 gap-y-2 border-b border-white/5 px-4 py-3.5 text-left transition-colors last:border-b-0 hover:bg-white/[0.035] sm:grid-cols-[minmax(0,1fr)_auto_auto] sm:items-center"
                  >
                    <span className="flex min-w-0 items-center gap-3">
                      <ItemSprite item={row} itemKey={match.itemKey} size="sm" />
                      <span className="min-w-0">
                        <span className="block truncate font-heading text-sm font-bold text-[var(--text-primary)] transition-colors group-hover:text-emerald-400">{row?.name || match.itemKey}</span>
                        <span className="mt-0.5 block font-mono text-[9px] uppercase tracking-wider text-[var(--text-muted)]">
                          {match.listingCount} offer{match.listingCount === 1 ? "" : "s"} · median {row?.median > 0 ? fmt(row.median) : "unavailable"}
                        </span>
                      </span>
                    </span>
                    <span className="text-right sm:min-w-24">
                      <span className="block font-mono text-sm font-semibold tabular-nums text-[var(--text-primary)]">{priceLabel}</span>
                      <span className="block font-mono text-[9px] uppercase tracking-wider text-[var(--text-muted)]">asking each</span>
                    </span>
                    <span className="col-span-2 flex items-center justify-between gap-3 pl-11 sm:col-span-1 sm:block sm:min-w-36 sm:pl-0 sm:text-right">
                      <MarkupLabel range={range} tone={tone} />
                      <span className="block font-mono text-[9px] text-[var(--text-muted)] sm:mt-1">
                        {range ? `${row.confidence} confidence` : "identity or median unavailable"} · {match.latestSeenMs ? fmtTime(match.latestSeenMs) : "unknown age"}
                      </span>
                    </span>
                  </button>
                );
              })}
            </div>

            {sellerItems?.hasMore && (
              <button
                type="button"
                onClick={sellerItems.loadMore}
                disabled={loadingMore}
                className="mt-3 inline-flex items-center gap-2 rounded-md border border-white/10 px-3 py-2 text-xs text-[var(--text-secondary)] transition-colors hover:border-amber-500/40 hover:text-[var(--text-primary)] disabled:opacity-50"
              >
                {loadingMore ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <ChevronDown className="h-3.5 w-3.5" />}
                Load more listings
              </button>
            )}
            <p className="mt-3 text-xs leading-relaxed text-[var(--text-muted)]">
              “Vs median” uses only matching item, tier, and variant identities. Grouped offers show a range when their asking prices differ.
            </p>
          </section>

          <div className="flex flex-col gap-2 sm:flex-row">
            <button
              data-testid="seller-view-listings"
              onClick={() => onFilterListings(seller.name)}
              className="inline-flex flex-1 items-center justify-between gap-3 rounded-lg border border-emerald-500/30 bg-emerald-500/10 px-4 py-3 text-sm font-semibold text-emerald-700 transition-colors hover:border-emerald-500/60 hover:bg-emerald-500/15 dark:text-emerald-300"
            >
              Filter the Market <ArrowUpRight className="w-4 h-4" />
            </button>
            <button
              type="button"
              onClick={() => navigate(`/sellers/${encodeURIComponent(seller.name)}`)}
              className="inline-flex items-center justify-center gap-2 rounded-lg border border-white/10 bg-white/[0.03] px-4 py-3 text-sm text-[var(--text-secondary)] transition-colors hover:border-white/25 hover:text-[var(--text-primary)]"
            >
              Full profile <ExternalLink className="h-3.5 w-3.5" />
            </button>
            <button
              data-testid="seller-block-toggle"
              aria-label={isBlocked ? `Unblock ${seller.name}` : `Block ${seller.name}`}
              onClick={() => blocklist.toggle(seller.name)}
              className={`inline-flex items-center justify-center gap-2 rounded-lg border px-4 py-3 text-sm transition-colors ${isBlocked ? "border-red-500/30 bg-red-500/10 text-red-400" : "border-white/10 bg-white/[0.03] text-[var(--text-muted)] hover:border-red-500/30 hover:text-red-400"}`}
            >
              <BellOff className="w-4 h-4" /> <span className="sm:sr-only">{isBlocked ? "Unblock seller" : "Block seller"}</span>
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

function MarkupLabel({ range, tone }) {
  const tones = {
    high: "text-red-600 dark:text-red-300",
    above: "text-amber-700 dark:text-amber-300",
    below: "text-emerald-700 dark:text-emerald-300",
    aligned: "text-sky-700 dark:text-sky-300",
    neutral: "text-[var(--text-muted)]",
  };
  return (
    <span data-testid="seller-listing-markup" className={`block text-xs font-semibold ${tones[tone] || tones.neutral}`}>
      {formatSellerMarkupRange(range)}
    </span>
  );
}

function KPI({ l, v, c = "text-white" }) {
  return (
    <div className="bg-bg-base px-4 py-4">
      <div className="font-mono text-[9px] uppercase tracking-[0.25em] text-zinc-500 mb-1">{l}</div>
      <div className={`font-heading text-xl font-bold tabular ${c}`}>{v}</div>
    </div>
  );
}

// ---------- DetailDrawer (the universal shell) ----------
//
// Listens for ?item=<key> (item preview) and ?sellerView=<name>
// (seller preview) on the current URL and slides in a panel with
// the corresponding content. Both modes coexist; the user can
// switch from an item to a seller (via the trail) without leaving
// the current page.
//
// The drawer is mounted once at the App level so any page can
// trigger it via openItem() / openSellerInDrawer() without needing
// to know about the shell.

export default function DetailDrawer() {
  const [searchParams, setSearchParams] = useSearchParams();
  const navigate = useNavigate();
  const { pathname } = useLocation();
  // Legacy Shops links use item as a search filter, never an auction drawer.
  const itemKey = pathname === "/shops" ? null : searchParams.get("item");
  const sellerName = searchParams.get("sellerView");
  const shopItem = searchParams.get("shopItem");
  const shopLocation = searchParams.get("shopLocation");
  const shopVariant = searchParams.get("shopVariant");
  const isOpen = !!(itemKey || sellerName || shopItem || shopLocation);
  const previousFocusRef = useRef(null);
  const drawerRef = useRef(null);
  const prefersReduced = useReducedMotion();
  useScrollLock(isOpen);

  const close = useCallback(() => {
    const next = new URLSearchParams(searchParams);
    next.delete("item");
    next.delete("sellerView");
    next.delete("shopItem");
    next.delete("shopLocation"); next.delete("shopVariant"); next.delete("shopTier"); next.delete("shopSet");
    setSearchParams(next, { replace: true });
  }, [searchParams, setSearchParams]);

  const closeRef = useRef(close);
  useEffect(() => { closeRef.current = close; }, [close]);

  const openSeller = (name) => {
    const next = new URLSearchParams(searchParams);
    next.delete("item");
    next.delete("shopItem");
    next.delete("shopLocation"); next.delete("shopVariant"); next.delete("shopTier"); next.delete("shopSet");
    next.set("sellerView", name);
    setSearchParams(next);
  };

  const openItemFromSeller = (key) => {
    // Keep sellerView so the item panel can offer Back-to-seller. The
    // branch order below still prefers the item panel when both are set.
    const next = new URLSearchParams(searchParams);
    next.set("item", key);
    setSearchParams(next);
    pushRecentlyViewed(key);
  };

  const filterListings = (name) => {
    close();
    navigate(`/market?seller=${encodeURIComponent(name)}`);
  };

  // Return from an item opened inside the seller panel: drop only `item`
  // so the seller panel restores underneath.
  const backToSeller = useCallback(() => {
    const next = new URLSearchParams(searchParams);
    next.delete("item");
    setSearchParams(next);
  }, [searchParams, setSearchParams]);

  // Return from the per-item shop view opened via Compare: drop only the
  // shopItem family so the location panel restores underneath.
  const backToShop = useCallback(() => {
    const next = new URLSearchParams(searchParams);
    next.delete("shopItem"); next.delete("shopVariant"); next.delete("shopTier"); next.delete("shopSet");
    setSearchParams(next);
  }, [searchParams, setSearchParams]);

  // ESC to close + focus management while open (scroll is handled by useScrollLock)
  useEffect(() => {
    if (!isOpen) return;

    previousFocusRef.current = document.activeElement;

    const handler = (e) => { if (e.key === "Escape") closeRef.current(); };
    document.addEventListener("keydown", handler);

    // Initial focus on the drawer panel after animation
    requestAnimationFrame(() => {
      const closeBtn = document.querySelector('[data-testid="drawer-close"]');
      if (closeBtn) closeBtn.focus();
    });

    return () => {
      document.removeEventListener("keydown", handler);
      previousFocusRef.current?.focus();
    };
  }, [isOpen]);

  // Focus trap: keep Tab cycling inside the drawer while open
  useEffect(() => {
    if (!isOpen) return;
    const drawer = drawerRef.current;
    if (!drawer) return;
    const onKeyDown = (e) => {
      if (e.key !== "Tab") return;
      const focusable = drawer.querySelectorAll(
        'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])',
      );
      if (focusable.length === 0) return;
      const first = focusable[0];
      const last = focusable[focusable.length - 1];
      if (e.shiftKey) {
        if (document.activeElement === first) {
          e.preventDefault();
          last.focus();
        }
      } else {
        if (document.activeElement === last) {
          e.preventDefault();
          first.focus();
        }
      }
    };
    document.addEventListener("keydown", onKeyDown);
    return () => document.removeEventListener("keydown", onKeyDown);
  }, [isOpen]);

  return (
    <AnimatePresence>
      {isOpen && (
        <>
          <motion.div
            key="backdrop"
            initial={prefersReduced ? undefined : { opacity: 0 }}
            animate={prefersReduced ? undefined : { opacity: 1 }}
            exit={prefersReduced ? undefined : { opacity: 0 }}
            transition={{ duration: 0.25 }}
            onClick={close}
            data-testid="drawer-backdrop"
            className="fixed inset-0 z-50 drawer-backdrop"
          />
          <motion.aside
            ref={drawerRef}
            key="drawer"
            initial={prefersReduced ? undefined : { x: "100%" }}
            animate={prefersReduced ? undefined : { x: 0 }}
            exit={prefersReduced ? undefined : { x: "100%" }}
            transition={{ duration: 0.45, ease: [0.16, 1, 0.3, 1] }}
            data-testid="detail-drawer"
            className={`fixed top-0 right-0 bottom-0 z-50 w-full ${(shopItem || shopLocation) ? "sm:w-[min(880px,94vw)]" : "sm:w-[min(680px,92vw)]"} bg-bg-base border-l border-white/10 shadow-[-30px_0_80px_rgba(0,0,0,0.6)] flex flex-col`}
            role="dialog"
            aria-modal="true"
            aria-label={itemKey ? "Item detail" : sellerName ? "Seller detail" : shopItem ? "Chest shop detail" : "Detail panel"}
          >
            {shopItem ? (
              <ShopDetailPanel key={`${shopItem}|${shopVariant}|${searchParams.get("shopTier")}|${searchParams.get("shopSet")}`}
                itemName={shopItem} variant={shopVariant} tier={searchParams.get("shopTier")} setName={searchParams.get("shopSet")}
                onClose={close} onOpenSeller={openSeller} onOpenLocation={row => openShopDetail(searchParams, setSearchParams, row)}
                shopReturn={shopLocation} onBackToLocation={backToShop} />
            ) : shopLocation ? (
              <ShopLocationPanel locationKey={shopLocation} onClose={close}
                onSelect={row => openShopDetail(searchParams, setSearchParams, row)}
                onCompare={row => {
                  // Keep shopLocation so the per-item view can offer Back.
                  // The branch order above prefers shopItem when both set.
                  const next = new URLSearchParams(searchParams);
                  next.set("shopItem", row.itemName || row.displayItemName);
                  next.set("shopVariant", row.variantKey || "");
                  next.set("shopTier", String(row.tier || 0));
                  next.set("shopSet", row.setName || "None");
                  setSearchParams(next);
                }} />
            ) : itemKey ? (
              <ItemDetailContent itemKey={itemKey} onClose={close} onOpenSeller={openSeller} sellerReturn={sellerName} onBackToSeller={backToSeller} />
            ) : sellerName ? (
              <SellerPanel sellerName={sellerName} onClose={close} onFilterListings={filterListings} onOpenItem={openItemFromSeller} />
            ) : null}
          </motion.aside>
        </>
      )}
    </AnimatePresence>
  );
}

// Convenience helpers for opening the drawer from anywhere
export function openItem(searchParams, setSearchParams, itemKey) {
  const next = new URLSearchParams(searchParams);
  next.delete("shopLocation"); next.delete("shopVariant"); next.delete("shopItem"); next.delete("shopTier"); next.delete("shopSet");
  next.delete("sellerView");
  next.set("item", itemKey);
  setSearchParams(next);
  
  // Record this view in recently viewed
  pushRecentlyViewed(itemKey);
}
export function openSellerInDrawer(searchParams, setSearchParams, name) {
  const next = new URLSearchParams(searchParams);
  next.delete("shopLocation"); next.delete("shopVariant"); next.delete("shopTier"); next.delete("shopSet");
  next.delete("item");
  next.delete("shopItem");
  next.set("sellerView", name);
  setSearchParams(next);
}
export function openShopDetail(searchParams, setSearchParams, itemName) {
  const next = new URLSearchParams(searchParams);
  next.delete("item");
  next.delete("sellerView");
  next.delete("shopLocation"); next.delete("shopVariant"); next.delete("shopItem"); next.delete("shopTier"); next.delete("shopSet");
  if (typeof itemName === "object") next.set("shopLocation", shopLocationKey(itemName));
  else next.set("shopItem", itemName);
  setSearchParams(next);
}
