import { useEffect, useRef, useState } from "react";
import { useReducedMotion } from "framer-motion";
import { isPrismaticItem } from "@/lib/itemPresentation";

const DEFAULT_ANGLE = { x: -4, y: -8 };
const X_LIMIT = 22;
const Y_LIMIT = 34;
const DEPTH_LAYERS = 9;
const HINT_KEY = "castia.spriteHintSeen";

function clamp(value, min, max) {
  return Math.min(max, Math.max(min, value));
}

function extrusionTransform(depth, layerCount, angle) {
  const ratio = depth / layerCount;
  // Rear layers shift opposite the rotation delta so turning the sprite
  // reveals a thin edge instead of sliding the whole stack sideways.
  // At rest (DEFAULT_ANGLE) the offset is zero and only Z depth remains.
  const offsetX = -((angle.y - DEFAULT_ANGLE.y) / Y_LIMIT) * 6 * ratio;
  const offsetY = ((angle.x - DEFAULT_ANGLE.x) / X_LIMIT) * 4 * ratio;
  return `translate3d(${offsetX}px, ${offsetY}px, -${depth * 0.35}px)`;
}

export default function InteractiveItemSprite({ image, itemName }) {
  const prefersReducedMotion = useReducedMotion();
  const stackRef = useRef(null);
  const shineRef = useRef(null);
  const layerRefs = useRef([]);
  const frameRef = useRef(null);
  const springRef = useRef(null);
  const angleRef = useRef({ ...DEFAULT_ANGLE });
  const dragRef = useRef(null);
  const [failed, setFailed] = useState(false);
  // Fewer extrusion layers on touch devices: same look at sprite scale,
  // far fewer composited layers per hero.
  const [layerCount] = useState(() => {
    try {
      return window.matchMedia && window.matchMedia("(pointer: coarse)").matches ? 5 : DEPTH_LAYERS;
    } catch { return DEPTH_LAYERS; }
  });
  // One-time "drag to rotate" hint: visible until the first interaction,
  // then falls back to the hover/focus affordance.
  const [hintSeen, setHintSeen] = useState(() => {
    try { return localStorage.getItem(HINT_KEY) === "seen"; } catch { return true; }
  });
  const dismissHint = () => {
    if (hintSeen) return;
    try { localStorage.setItem(HINT_KEY, "seen"); } catch { /* ignore */ }
    setHintSeen(true);
  };

  const paint = (angle = angleRef.current) => {
    if (stackRef.current) {
      stackRef.current.style.transform = `rotateX(${angle.x}deg) rotateY(${angle.y}deg)`;
    }
    if (shineRef.current) {
      shineRef.current.style.backgroundPosition = `${50 - angle.y * 1.25}% ${50 + angle.x * 1.4}%`;
      const base = Number(shineRef.current.dataset.baseOpacity || 0.42);
      shineRef.current.style.opacity = String(base + Math.min(0.22, (Math.abs(angle.x) + Math.abs(angle.y)) / 180));
    }
    const layers = layerRefs.current.filter(Boolean);
    const layerCount = layers.length;
    layers.forEach((layer, index) => {
      const depth = layerCount - index;
      layer.style.transform = extrusionTransform(depth, layerCount, angle);
    });
  };

  const schedulePaint = () => {
    if (frameRef.current) return;
    frameRef.current = requestAnimationFrame(() => {
      frameRef.current = null;
      paint();
    });
  };

  const cancelSpring = () => {
    if (springRef.current) {
      cancelAnimationFrame(springRef.current);
      springRef.current = null;
    }
  };

  // Gentle ease back toward rest so a drag never leaves the sprite stuck
  // at an awkward angle and small overshoots settle instead of snapping.
  const springBack = () => {
    cancelSpring();
    const from = { ...angleRef.current };
    const to = { ...DEFAULT_ANGLE };
    const done = () => {
      if (stackRef.current) stackRef.current.classList.remove("will-change-transform");
    };
    if (Math.abs(from.x - to.x) < 0.05 && Math.abs(from.y - to.y) < 0.05) {
      angleRef.current = to;
      paint();
      done();
      return;
    }
    const start = performance.now();
    const duration = 550;
    const tick = (now) => {
      const t = Math.min(1, (now - start) / duration);
      const eased = 1 - Math.pow(1 - t, 3);
      angleRef.current = {
        x: from.x + (to.x - from.x) * eased,
        y: from.y + (to.y - from.y) * eased,
      };
      paint();
      if (t < 1) {
        springRef.current = requestAnimationFrame(tick);
      } else {
        springRef.current = null;
        done();
      }
    };
    springRef.current = requestAnimationFrame(tick);
  };

  const reset = () => {
    cancelSpring();
    angleRef.current = { ...DEFAULT_ANGLE };
    dragRef.current = null;
    if (stackRef.current) stackRef.current.classList.remove("will-change-transform");
    paint();
    dismissHint();
  };

  useEffect(() => {
    setFailed(false);
    cancelSpring();
    angleRef.current = { ...DEFAULT_ANGLE };
    paint();
    return () => {
      if (frameRef.current) cancelAnimationFrame(frameRef.current);
      cancelSpring();
      try {
        document.documentElement.style.userSelect = "";
        document.body.style.userSelect = "";
      } catch { /* noop */ }
    };
  }, [image?.src]);

  if (!image || failed) return null;

  const prismatic = isPrismaticItem({ key: itemName, name: itemName });
  const spriteClass = `absolute inset-0 h-full w-full object-contain select-none pointer-events-none ${image.pixelated ? "[image-rendering:pixelated]" : ""}`;
  // Animated sources get no silhouette glare: the mask and the sprite run
  // on separate animation clocks that can drift a frame apart, which reads
  // as a detached ghost during fast phases. The animation itself carries
  // the eye-candy; static sprites keep the full masked glare.
  const animated = !!image.animated;
  const sheenMask = {
    WebkitMask: `url(${image.src}) center / contain no-repeat`,
    mask: `url(${image.src}) center / contain no-repeat`,
  };

  if (prefersReducedMotion) {
    return (
      <div
        data-testid="item-hero-sprite"
        role="img"
        aria-label={`${itemName} item preview`}
        className="relative h-24 w-24 sm:h-36 sm:w-36 lg:h-40 lg:w-40 shrink-0 max-w-full overflow-visible"
      >
        <div className="absolute inset-[30%] rounded-full bg-emerald-400/20 blur-xl sm:blur-2xl dark:bg-emerald-400/15" aria-hidden="true" />
        <img src={image.src} alt="" onError={() => setFailed(true)} className={`${spriteClass} ${prismatic ? "animate-prismatic" : ""}`} />
        {!animated && (
          <div
            aria-hidden="true"
            className="absolute inset-0 opacity-35 mix-blend-screen"
            style={{
              background: "linear-gradient(118deg, transparent 25%, rgba(255,255,255,.78) 43%, rgba(190,255,235,.35) 49%, transparent 66%) 46% 50% / 220% 220%",
              ...sheenMask,
            }}
          />
        )}
      </div>
    );
  }

  const updateAngle = (next) => {
    angleRef.current = {
      x: clamp(next.x, -X_LIMIT, X_LIMIT),
      y: clamp(next.y, -Y_LIMIT, Y_LIMIT),
    };
    schedulePaint();
  };

  const onPointerDown = (event) => {
    if (event.button !== 0) return;
    cancelSpring();
    dismissHint();
    // Compositing hint only while interacting: the stack animates via
    // rAF the rest of the time without a permanent layer reservation.
    if (stackRef.current) stackRef.current.classList.add("will-change-transform");
    // Prevent the browser from starting a text selection when the drag
    // sweeps across the title/price next to the sprite.
    event.preventDefault();
    try {
      document.documentElement.style.userSelect = "none";
      document.body.style.userSelect = "none";
    } catch { /* noop: non-DOM test env */ }
    event.currentTarget.setPointerCapture(event.pointerId);
    dragRef.current = {
      pointerId: event.pointerId,
      startX: event.clientX,
      startY: event.clientY,
      angleX: angleRef.current.x,
      angleY: angleRef.current.y,
    };
  };

  const onPointerMove = (event) => {
    const drag = dragRef.current;
    if (!drag || drag.pointerId !== event.pointerId) return;
    // Grab-natural: drag right turns the right edge toward you,
    // drag down tips the top toward you. Matches the extrusion direction
    // so the edge reveals instead of sliding.
    updateAngle({
      x: drag.angleX + (event.clientY - drag.startY) * 0.3,
      y: drag.angleY - (event.clientX - drag.startX) * 0.35,
    });
  };

  const endDrag = (event) => {
    if (dragRef.current?.pointerId !== event.pointerId) return;
    dragRef.current = null;
    try {
      document.documentElement.style.userSelect = "";
      document.body.style.userSelect = "";
    } catch { /* noop */ }
    if (event.currentTarget.hasPointerCapture(event.pointerId)) {
      event.currentTarget.releasePointerCapture(event.pointerId);
    }
    springBack();
  };

  const onKeyDown = (event) => {
    const step = event.shiftKey ? 8 : 3;
    const keys = ["ArrowLeft", "ArrowRight", "ArrowUp", "ArrowDown", "Home", "Escape", "r", "R"];
    if (!keys.includes(event.key)) return;
    event.preventDefault();
    dismissHint();
    if (["Home", "Escape", "r", "R"].includes(event.key)) {
      reset();
      return;
    }
    cancelSpring();
    updateAngle({
      x: angleRef.current.x + (event.key === "ArrowDown" ? step : event.key === "ArrowUp" ? -step : 0),
      y: angleRef.current.y + (event.key === "ArrowLeft" ? step : event.key === "ArrowRight" ? -step : 0),
    });
  };

  return (
    <div data-ambient className="group relative h-24 w-24 sm:h-36 sm:w-36 lg:h-40 lg:w-40 shrink-0 max-w-full overflow-visible select-none">
      <div className="absolute inset-[30%] rounded-full bg-emerald-400/25 blur-xl sm:blur-2xl dark:bg-emerald-400/15" aria-hidden="true" />
      <div
        data-testid="item-hero-sprite"
        role="group"
        tabIndex={0}
        aria-label={`Interactive preview of ${itemName}. Drag to rotate (releases back to rest); arrow keys rotate, Home, Escape, or R resets.`}
        onPointerDown={onPointerDown}
        onPointerMove={onPointerMove}
        onPointerUp={endDrag}
        onPointerCancel={endDrag}
        onDoubleClick={reset}
        onKeyDown={onKeyDown}
        onDragStart={(event) => event.preventDefault()}
        title="Drag to rotate — releases back to rest"
        className="absolute inset-0 isolate cursor-grab active:cursor-grabbing touch-pan-y select-none outline-none rounded-xl focus-visible:ring-2 focus-visible:ring-emerald-400/80 focus-visible:ring-offset-2 focus-visible:ring-offset-[rgb(var(--bg-base))] after:absolute after:-inset-4 after:content-['']"
        style={{ perspective: "620px", perspectiveOrigin: "50% 50%" }}
      >
        <div
          ref={stackRef}
          className={`relative h-full w-full ${prismatic ? "animate-prismatic" : ""}`}
          style={{ transform: `rotateX(${DEFAULT_ANGLE.x}deg) rotateY(${DEFAULT_ANGLE.y}deg)`, transformStyle: "preserve-3d" }}
        >
          {Array.from({ length: image.animated ? 5 : layerCount }, (_, index) => {
            const count = image.animated ? 5 : layerCount;
            const depth = count - index;
            return (
              <img
                key={depth}
                ref={(node) => { layerRefs.current[index] = node; }}
                src={image.src}
                alt=""
                aria-hidden="true"
                draggable="false"
                className={spriteClass}
                style={{
                  transform: extrusionTransform(depth, count, DEFAULT_ANGLE),
                  filter: `brightness(${0.3 + index * (0.2 / layerCount)}) saturate(1.14) contrast(1.06)`,
                  opacity: 1,
                  backfaceVisibility: "visible",
                }}
              />
            );
          })}
          <img
            src={image.src}
            alt=""
            draggable="false"
            loading="lazy"
            decoding="async"
            onError={() => setFailed(true)}
            className={`${spriteClass} drop-shadow-[0_12px_14px_rgb(0_0_0/0.35)]`}
            style={{ transform: "translateZ(1px)" }}
          />
          {!animated && (
            <div
              ref={shineRef}
              aria-hidden="true"
              data-base-opacity={0.42}
              className="absolute inset-0 pointer-events-none mix-blend-screen transition-opacity duration-150"
              style={{
                transform: "translateZ(2px)",
                opacity: 0.46,
                background: "linear-gradient(118deg, transparent 24%, rgba(255,255,255,.92) 43%, rgba(188,255,231,.42) 49%, transparent 67%) 60% 44% / 225% 225%",
                ...sheenMask,
              }}
            />
          )}
        </div>
      </div>
      <span className={`pointer-events-none absolute -bottom-3 left-1/2 -translate-x-1/2 whitespace-nowrap font-mono text-[8px] uppercase tracking-[0.18em] text-[var(--text-muted)] transition-opacity ${hintSeen ? "opacity-0 group-focus-within:opacity-100 sm:group-hover:opacity-100" : "opacity-100"}`}>
        Drag to rotate
      </span>
    </div>
  );
}
